// HakSpring Romanizer (Romaine) - 「蘿蔓生菜」客語羅馬字轉換器
// Written by Roo, the AI Software Engineer
// Based on spec 1.4 generated by Gemini 2.5 Pro based on ideas of Aiuanyu

document.addEventListener('DOMContentLoaded', () => {
  // DOM Elements
  const showRomanizerBtn = document.getElementById('showRomanizerBtn');
  const romanizerModal = document.getElementById('romanizerModal');
  const romanizerCloseBtn = document.getElementById('romanizerCloseBtn');
  const romanizerStartBtn = document.getElementById('romanizer-start-btn');
  const segmentationWorkspace = document.getElementById('segmentation-workspace');
  const copyRomanizerResultBtn = document.getElementById('copy-romanizer-result-btn');
  const romanizerDialectSelector = document.getElementById('romanizer-dialect-selector');
  const romanizerInput = document.getElementById('romanizer-input');
  const romanizerOutput = document.getElementById('romanizer-output');

  // Event Listeners
  if (showRomanizerBtn) {
    showRomanizerBtn.addEventListener('click', showRomanizer);
  }
  if (romanizerCloseBtn) {
    romanizerCloseBtn.addEventListener('click', hideRomanizer);
  }
  if (romanizerStartBtn) {
    romanizerStartBtn.addEventListener('click', startSegmentation);
  }
  if (segmentationWorkspace) {
    segmentationWorkspace.addEventListener('click', handleSegmentClick);
  }
  if (copyRomanizerResultBtn) {
    copyRomanizerResultBtn.addEventListener('click', copyRomanizerResult);
  }

  // --- Functions ---

  // Placeholder functions to be implemented later
  function showRomanizer() {
    if (romanizerModal) {
      romanizerModal.classList.add('is-visible');
      // Sync dialect selector with global variable from main.js
      if (typeof currentActiveMainDialectName !== 'undefined' && romanizerDialectSelector) {
        romanizerDialectSelector.value = currentActiveMainDialectName;
      }
    }
  }

  function hideRomanizer() {
    if (romanizerModal) {
      romanizerModal.classList.remove('is-visible');
    }
  }
  function startSegmentation() {
    if (!romanizerInput || !segmentationWorkspace || !romanizerOutput) return;

    // 1. Clear previous results
    segmentationWorkspace.innerHTML = '';
    romanizerOutput.innerHTML = '';

    // 2. Get input text
    const text = romanizerInput.value;
    if (!text) return;

    // 3. Define segmentation regex (Han characters vs. others)
    // This regex splits the string by sequences of non-Han characters, keeping the delimiters.
    // The regex for CJK Unified Ideographs is \u4e00-\u9fa5. We add common extensions.
    const segmentRegex = /([^\u4e00-\u9fa5\u3400-\u4dbf\u{20000}-\u{2a6df}\u{2a700}-\u{2b73f}\u{2b740}-\u{2b81f}\u{2b820}-\u{2ceaf}\u{2ceb0}-\u{2ebef}]+)/u;
    const segments = text.split(segmentRegex).filter(Boolean); // filter(Boolean) removes empty strings

    // 4. & 5. Create and append spans
    segments.forEach(segment => {
      const span = document.createElement('span');
      span.textContent = segment;

      // 6. Add class to word segments for click handling
      // If the segment does NOT match the non-Han regex, it's a word.
      if (!segmentRegex.test(segment)) {
        span.classList.add('segment-word');
      }
      
      segmentationWorkspace.appendChild(span);
    });
  }
  function handleSegmentClick(event) {
    const target = event.target;
    // Make sure the clicked element is a word segment
    if (target.classList.contains('segment-word')) {
      const searchText = target.textContent;
      
      // Check if dependent functions from main.js exist
      if (typeof findPronunciationsInAllData !== 'function' || typeof showPronunciationPopup !== 'function') {
        console.error('Core functions (findPronunciationsInAllData or showPronunciationPopup) are not defined. Make sure main.js is loaded before romanizer.js.');
        alert('核心查詢功能載入失敗，請重新整理頁面。');
        return;
      }
      
      const readings = findPronunciationsInAllData(searchText);
      
      // Call the popup function, passing the clicked span as the anchor,
      // and a new callback function to handle the selection.
      // Call the new, self-contained popup function
      showPronunciationPopup(searchText, readings, target, (anchor, phonetic) => {
        updateRomanizerOutput(anchor, phonetic);
      });
    }
  }
  function copyRomanizerResult() {
    if (!romanizerOutput || !copyRomanizerResultBtn) return;
    const textToCopy = romanizerOutput.textContent;
    if (textToCopy) {
      navigator.clipboard.writeText(textToCopy).then(() => {
        // Optional: Provide user feedback
        const originalButtonContent = copyRomanizerResultBtn.innerHTML;
        copyRomanizerResultBtn.innerHTML = '<i class="fas fa-check"></i> 已複製';
        copyRomanizerResultBtn.disabled = true;
        setTimeout(() => {
          copyRomanizerResultBtn.innerHTML = originalButtonContent;
          copyRomanizerResultBtn.disabled = false;
        }, 2000);
      }).catch(err => {
        console.error('無法複製文字: ', err);
        alert('複製失敗，請手動複製。');
      });
    }
  }
  function updateRomanizerOutput(targetSpan, selectedRomanization) {
    if (!targetSpan || !romanizerOutput || !segmentationWorkspace) return;

    // 1. & 2. Set data attribute and add 'completed' class
    targetSpan.dataset.romanized = selectedRomanization;
    targetSpan.classList.add('completed');

    // 3. & 4. & 5. Iterate through all spans to rebuild the output string
    const allSpans = segmentationWorkspace.querySelectorAll('span');
    let resultString = '';
    allSpans.forEach(span => {
      // Use the stored romanization if available, otherwise use the original text (for punctuation)
      const text = span.dataset.romanized || span.textContent;
      resultString += text + ' ';
    });

    // Update the output display, trimming trailing space
    romanizerOutput.textContent = resultString.trim();
  }
});